    Eq(StatusFor(new Invalid(new List<string> { "email is required" })), 400));

Test("Invalid without errors is a server bug: 500 (boundary)", () =>
    Eq(StatusFor(new Invalid(new List<string>())), 500));

Test("null and unknown results are 500", () =>
{
    Eq(StatusFor(null), 500);
    Eq(StatusFor(new Unexpected()), 500);
});

